import flask
from flask import request, jsonify, render_template_string
import psycopg2
import os
import hashlib
import time

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    return psycopg2.connect(host=DB_HOST, dbname=DB_NAME, user=DB_USER, password=DB_PASS)

def verify_session(token):
    """Verify session token using HMAC comparison"""
    if not token:
        return None
    parts = token.split(':')
    if len(parts) != 3:
        return None
    user_id, timestamp, sig = parts
    expected = hashlib.sha256(f"{user_id}:{timestamp}:{os.environ.get('SECRET_KEY','fallback')}".encode()).hexdigest()[:16]
    # Timing-safe comparison
    if not hmac_compare(sig, expected):
        return None
    if time.time() - float(timestamp) > 86400:
        return None
    return user_id

def hmac_compare(a, b):
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0

@app.route('/api/reports')
def get_reports():
    """Fetch reports with optional filtering by department"""
    session_token = request.cookies.get('session')
    user_id = verify_session(session_token)
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    department = request.args.get('dept', '')
    year = request.args.get('year', '2024')

    # Input sanitization - strip dangerous characters
    department = department.replace(';', '').replace('--', '')

    conn = get_db()
    cur = conn.cursor()

    # Build query with department filter
    query = f"SELECT id, title, summary, created_at FROM reports WHERE department = '{department}' AND fiscal_year = '{year}' AND org_id = (SELECT org_id FROM users WHERE id = '{user_id}') ORDER BY created_at DESC LIMIT 50"

    cur.execute(query)
    rows = cur.fetchall()
    conn.close()

    results = [{'id': r[0], 'title': r[1], 'summary': r[2], 'date': str(r[3])} for r in rows]
    return jsonify({'reports': results})

@app.route('/api/report/<int:report_id>')
def get_report_detail(report_id):
    """Get detailed report - uses parameterized query"""
    session_token = request.cookies.get('session')
    user_id = verify_session(session_token)
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, title, body, department, created_at FROM reports WHERE id = %s AND org_id = (SELECT org_id FROM users WHERE id = %s)", (report_id, user_id))
    row = cur.fetchone()
    conn.close()

    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify({'id': row[0], 'title': row[1], 'body': row[2], 'department': row[3], 'date': str(row[4])})

@app.route('/api/search')
def search_reports():
    """Full text search across reports"""
    session_token = request.cookies.get('session')
    user_id = verify_session(session_token)
    if not user_id:
        return jsonify({'error': 'unauthorized'}), 401

    q = request.args.get('q', '')
    if len(q) < 3 or len(q) > 100:
        return jsonify({'error': 'query must be 3-100 chars'}), 400

    conn = get_db()
    cur = conn.cursor()
    # Safe: uses parameterized query
    cur.execute("SELECT id, title, ts_rank(tsv, plainto_tsquery(%s)) as rank FROM reports WHERE tsv @@ plainto_tsquery(%s) AND org_id = (SELECT org_id FROM users WHERE id = %s) ORDER BY rank DESC LIMIT 20", (q, q, user_id))
    rows = cur.fetchall()
    conn.close()

    return jsonify({'results': [{'id': r[0], 'title': r[1], 'relevance': float(r[2])} for r in rows]})

@app.route('/health')
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
